// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;

    receive() external payable {}

    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // admissible domain: a real external player paying exactly the ticket price
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(uint160(actor) > 0xff); // avoid precompiles
        amount = bound(amount, 10, 10); // TICKET_AMOUNT

        // find a timestamp making the pseudo-random outcome a win (random == 0)
        uint256 ts = block.timestamp;
        vm.warp(ts);
        for (uint256 i = 0; i < 16; i++) {
            uint256 r = uint256(keccak256(abi.encodePacked(ts, block.difficulty, actor))) % 2;
            if (r == 0) break;
            ts++;
            vm.warp(ts);
        }

        vm.deal(actor, amount);
        vm.prank(actor);
        c.play{value: amount}();

        // General rule: the pot always mirrors the contract's ether balance.
        // In C, a winning round pays out the entire pot and resets it to 0,
        // so pot() == address(c).balance always holds; in the mutant the pot
        // stays at its pre-payout value while the balance is emptied.
        assertTrue(c.pot() == address(c).balance);
    }
}
